const badge = document.getElementById('spinning-badge');
const trans = document.getElementById('transition-box');
if (!badge || !trans) return false;
const style = document.getElementById('ai4a11y-motion-reducer-styles');
if (!style) {
  const cs = getComputedStyle(badge);
  return cs.animationName === 'spin';
}
const csBadge = getComputedStyle(badge);
const csTrans = getComputedStyle(trans);
const htmlCs = getComputedStyle(document.documentElement);
const animFast = csBadge.animationDuration === '0.000001s' || csBadge.animationDuration === '0.001ms' || parseFloat(csBadge.animationDuration) <= 0.001;
const animPaused = csBadge.animationPlayState === 'paused';
const transFast = csTrans.transitionDuration === '0.000001s' || csTrans.transitionDuration === '0.001ms' || parseFloat(csTrans.transitionDuration) <= 0.001;
const scrollAuto = htmlCs.scrollBehavior === 'auto';
return (animFast || animPaused) && transFast && scrollAuto;

const waapiBox = document.getElementById('waapi-box');
if (!waapiBox) return false;
const anims = waapiBox.getAnimations();
if (!anims.length) return false;
const style = document.getElementById('ai4a11y-motion-reducer-styles');
if (!style) {
  return anims[0].playState === 'running';
}
return anims[0].playState === 'paused';

const parallax = document.getElementById('parallax-section');
if (!parallax) return false;
const style = document.getElementById('ai4a11y-motion-reducer-styles');
const cs = getComputedStyle(parallax);
if (!style) {
  return cs.backgroundAttachment === 'fixed';
}
return cs.backgroundAttachment === 'scroll';

const autoVid = document.getElementById('autoplay-video');
const pausedVid = document.getElementById('paused-video');
if (!autoVid || !pausedVid) return false;
const style = document.getElementById('ai4a11y-motion-reducer-styles');
if (!style) {
  return autoVid.controls === false && pausedVid.controls === true;
}
if (autoVid.controls !== true || !autoVid.paused) return false;
if (pausedVid.controls !== true || !pausedVid.paused) return false;

// An autoplay video the person had already paused stays paused on disable().
const watched = document.getElementById('watched-video');
if (!watched || watched.dataset.ai4a11yWasPaused === 'false') return false;
if (autoVid.dataset.ai4a11yWasPaused !== 'false') return false;

autoVid.focus();
const focused = document.activeElement === autoVid;
autoVid.blur();
return focused;

const anim = document.getElementById('animated-gif');
const decor = document.getElementById('decorative-gif');
const ariaGif = document.getElementById('aria-labeled-gif');
const still = document.getElementById('still-image');
if (!anim || !decor || !ariaGif || !still) return false;

const style = document.getElementById('ai4a11y-motion-reducer-styles');
if (!style) {
  return anim.tagName === 'IMG' && decor.tagName === 'IMG' && ariaGif.tagName === 'IMG' && still.tagName === 'IMG';
}

// after enable: animated GIFs replaced with CANVAS
if (anim.tagName !== 'CANVAS' || anim.getAttribute('role') !== 'img' || anim.getAttribute('aria-label') !== 'Pulsing star animation') {
  return false;
}
if (decor.tagName !== 'CANVAS' || decor.getAttribute('aria-hidden') !== 'true') {
  return false;
}
if (ariaGif.tagName !== 'CANVAS' || ariaGif.getAttribute('role') !== 'img' || ariaGif.getAttribute('aria-label') !== 'Spinning loading indicator') {
  return false;
}
// no name: hidden, as decorative (a role="img" with no name is a barrier)
const unnamed = document.getElementById('unnamed-gif');
if (!unnamed || unnamed.tagName !== 'CANVAS' || unnamed.getAttribute('aria-hidden') !== 'true' || unnamed.hasAttribute('role')) return false;
// named by its title: the name once, not the same text again as a tooltip
const titled = document.getElementById('title-gif');
if (!titled || titled.tagName !== 'CANVAS' || titled.getAttribute('aria-label') !== 'Orbit diagram' || titled.hasAttribute('title')) return false;
// still image must remain an IMG
if (still.tagName !== 'IMG') return false;

return true;

const btn = document.getElementById('sample-button');
const p = document.getElementById('intro-para');
const copy = document.getElementById('footer-copy');
if (!btn || !p || !copy) return false;

btn.focus();
if (document.activeElement !== btn) return false;
let clicked = false;
const onClick = () => { clicked = true; };
btn.addEventListener('click', onClick, { once: true });
btn.click();
btn.blur();

const rect = btn.getBoundingClientRect();
const bigEnough = rect.width >= 24 && rect.height >= 24;

return clicked && bigEnough && p.textContent.includes('Standard content') && copy.textContent.includes('Motion Reducer Lab');
